sys_script.script:
/**
 * 16-Cancel reservation (72h rule)
 *
 * Blocks a state change to "Cancelled" when the reservation start date is less
 * than 72 hours away from now.
 */
(function executeRule(/** @type {any} */ current, /** @type {any} */ previous) {
    var CUTOFF_HOURS = 72;
    var MS_PER_HOUR = 60 * 60 * 1000;

    var startDate = current.getValue('start_date');
    if (!startDate) {
        return;
    }

    var start = new GlideDateTime(startDate + ' 00:00:00');
    var now = new GlideDateTime();
    var hoursUntilStart = (start.getNumericValue() - now.getNumericValue()) / MS_PER_HOUR;

    if (hoursUntilStart < CUTOFF_HOURS) {
        gs.addErrorMessage(
            'This reservation cannot be cancelled. Cancellations must be requested at least ' +
                CUTOFF_HOURS +
                ' hours before the rental start date (' +
                startDate +
                '). Please contact the rental desk for assistance.'
        );
        current.setAbortAction(true);
    }
})(current, previous);
